-- শুধু SELECT, কিছু বদলায় না। আমাদের ১২৫ জনের ব্যাচে ব্যবহৃত ৮০টা তারিখের
-- জন্যই শুধু সর্বোচ্চ serial সংখ্যা বের করা হচ্ছে (৮০ সারির বেশি হবে না,
-- ১০০-র সীমায় আটকাবে না)।

select
  substring("patientId" from 5 for 8) as date_part,
  max(substring("patientId" from 14)::int) as max_serial_used,
  count(*) as total_on_date
from public.patients
where "patientId" ~ '^JPE-\d{8}-\d+$'
  and substring("patientId" from 5 for 8) in (
    '05012025','11012025','12012025','13012025','18012025','19012025','25012025',
    '01022025','02022025','04022025','05022025','08022025','22022025',
    '01032025','04032025','08032025','15032025','18032025','29032025',
    '05042025','06042025','08042025','15042025','18042025','19042025','22042025','26042025','30042025',
    '03052025','06052025','10052025','13052025','17052025','18052025','24052025','27052025','29052025','31052025',
    '07062025','10062025','17062025','21062025','24062025','28062025',
    '08072025','12072025','22072025','29072025',
    '02082025','05082025','09082025','12082025','19082025','23082025','30082025','31082025',
    '06092025','09092025','16092025','20092025','22092025','23092025','27092025',
    '04102025','07102025','18102025','25102025','28102025',
    '15112025','23112025','25112025','29112025',
    '02122025','06122025','08122025','12122025','13122025','16122025','27122025','31122025'
  )
group by date_part
order by date_part;
